CREATE TABLE meta(key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE conversations(id TEXT PRIMARY KEY, title TEXT NOT NULL, channel TEXT NOT NULL, model TEXT NOT NULL, summary TEXT NOT NULL DEFAULT '', created_at INTEGER NOT NULL);
CREATE TABLE runs(id TEXT PRIMARY KEY, conversation_id TEXT NOT NULL REFERENCES conversations(id) ON DELETE CASCADE, request_id TEXT NOT NULL UNIQUE, source TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('queued','running','completed','failed','cancelled','interrupted')), partial TEXT NOT NULL DEFAULT '', error TEXT, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE messages(id TEXT PRIMARY KEY, conversation_id TEXT NOT NULL REFERENCES conversations(id) ON DELETE CASCADE, run_id TEXT REFERENCES runs(id) ON DELETE CASCADE, actor TEXT NOT NULL, role TEXT NOT NULL, text TEXT NOT NULL, body TEXT NOT NULL, event_at INTEGER NOT NULL, recorded_at INTEGER NOT NULL);
CREATE INDEX messages_conversation ON messages(conversation_id, recorded_at);
CREATE TABLE operations(id TEXT PRIMARY KEY, run_id TEXT NOT NULL REFERENCES runs(id) ON DELETE CASCADE, tool TEXT NOT NULL, args_hash TEXT NOT NULL, status TEXT NOT NULL, result TEXT, created_at INTEGER NOT NULL);
CREATE TABLE memories(id TEXT PRIMARY KEY, entity TEXT NOT NULL, kind TEXT NOT NULL, key TEXT NOT NULL, value TEXT NOT NULL, scope TEXT NOT NULL, source_id TEXT NOT NULL, basis TEXT NOT NULL, status TEXT NOT NULL, event_at INTEGER NOT NULL, recorded_at INTEGER NOT NULL, valid_until INTEGER, supersedes TEXT REFERENCES memories(id), version INTEGER NOT NULL DEFAULT 1);
CREATE INDEX memories_lookup ON memories(entity,key,status);
CREATE TABLE retrieval(id TEXT PRIMARY KEY, kind TEXT NOT NULL, text TEXT NOT NULL, source_id TEXT NOT NULL, event_at INTEGER NOT NULL, entity TEXT);
CREATE VIRTUAL TABLE retrieval_fts USING fts5(id UNINDEXED, text, tokenize='unicode61 remove_diacritics 2');
CREATE TRIGGER retrieval_insert AFTER INSERT ON retrieval BEGIN INSERT INTO retrieval_fts(id,text) VALUES(new.id,new.text); END;
CREATE TRIGGER retrieval_delete AFTER DELETE ON retrieval BEGIN DELETE FROM retrieval_fts WHERE id=old.id; END;
CREATE TRIGGER retrieval_update AFTER UPDATE ON retrieval BEGIN DELETE FROM retrieval_fts WHERE id=old.id; INSERT INTO retrieval_fts(id,text) VALUES(new.id,new.text); END;
CREATE TABLE vectors(id TEXT PRIMARY KEY REFERENCES retrieval(id) ON DELETE CASCADE, model TEXT NOT NULL, dimensions INTEGER NOT NULL, version TEXT NOT NULL, vector TEXT NOT NULL);
CREATE TABLE reviews(source_id TEXT PRIMARY KEY, status TEXT NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, error TEXT, next_at INTEGER NOT NULL DEFAULT 0);
CREATE TABLE deletions(hash TEXT PRIMARY KEY, deleted_at INTEGER NOT NULL);
CREATE TABLE skills(id TEXT NOT NULL, version INTEGER NOT NULL, name TEXT NOT NULL, scope TEXT NOT NULL, instructions TEXT NOT NULL, source_id TEXT NOT NULL, status TEXT NOT NULL, created_at INTEGER NOT NULL, PRIMARY KEY(id,version));
CREATE TABLE workflows(id TEXT PRIMARY KEY, definition TEXT NOT NULL, enabled INTEGER NOT NULL DEFAULT 1);
CREATE TABLE schedules(id TEXT PRIMARY KEY, definition TEXT NOT NULL, original TEXT NOT NULL, next_due INTEGER NOT NULL, status TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE INDEX schedules_due ON schedules(status,next_due);
CREATE TABLE occurrences(id TEXT PRIMARY KEY, schedule_id TEXT NOT NULL REFERENCES schedules(id), due_at INTEGER NOT NULL, status TEXT NOT NULL, lease_until INTEGER, attempts INTEGER NOT NULL DEFAULT 0, run_id TEXT, error TEXT);
CREATE TABLE outbox(id TEXT PRIMARY KEY, occurrence_id TEXT REFERENCES occurrences(id), destination TEXT NOT NULL, text TEXT NOT NULL, status TEXT NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, next_at INTEGER NOT NULL, remote_id TEXT, error TEXT, created_at INTEGER NOT NULL);
CREATE TABLE attachments(id TEXT PRIMARY KEY, conversation_id TEXT REFERENCES conversations(id) ON DELETE CASCADE, source_id TEXT, name TEXT NOT NULL, mime TEXT NOT NULL, bytes INTEGER NOT NULL, hash TEXT NOT NULL, transcript TEXT, status TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE mailbox(id TEXT PRIMARY KEY, cursor TEXT, last_sync INTEGER, error TEXT);
CREATE TABLE mail(id TEXT PRIMARY KEY, data TEXT NOT NULL, event_at INTEGER NOT NULL, imported_at INTEGER NOT NULL, announced INTEGER NOT NULL DEFAULT 0);
CREATE TABLE notification_rules(id TEXT PRIMARY KEY, definition TEXT NOT NULL, last_sent INTEGER, paused INTEGER NOT NULL DEFAULT 0);
CREATE TABLE feedback(notification_id TEXT PRIMARY KEY REFERENCES outbox(id), useful INTEGER NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE telegram_updates(id INTEGER PRIMARY KEY, data TEXT NOT NULL, status TEXT NOT NULL, error TEXT, received_at INTEGER NOT NULL);
CREATE TABLE extension_artifacts(hash TEXT PRIMARY KEY, extension_id TEXT NOT NULL, version TEXT NOT NULL, bundle TEXT NOT NULL, report TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE extension_installs(id TEXT PRIMARY KEY, active_hash TEXT REFERENCES extension_artifacts(hash), previous_hash TEXT REFERENCES extension_artifacts(hash), enabled INTEGER NOT NULL DEFAULT 0, failures INTEGER NOT NULL DEFAULT 0);
CREATE TABLE pending_actions(id TEXT PRIMARY KEY, kind TEXT NOT NULL, body TEXT NOT NULL, expires_at INTEGER NOT NULL, status TEXT NOT NULL, canonical_hash TEXT NOT NULL);
CREATE TABLE approvals(id TEXT PRIMARY KEY, operation TEXT NOT NULL, artifact_hash TEXT NOT NULL, canonical_hash TEXT NOT NULL, expires_at INTEGER NOT NULL, status TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE grants(id TEXT PRIMARY KEY, extension_id TEXT NOT NULL, artifact_hash TEXT NOT NULL, capability TEXT NOT NULL, selector TEXT NOT NULL, revoked INTEGER NOT NULL DEFAULT 0);
CREATE TABLE extension_storage(extension_id TEXT NOT NULL, key TEXT NOT NULL, value TEXT NOT NULL, state_version INTEGER NOT NULL DEFAULT 1, PRIMARY KEY(extension_id,key));
CREATE TABLE builds(id TEXT PRIMARY KEY, specification TEXT NOT NULL, status TEXT NOT NULL, artifact_hash TEXT, diagnostic TEXT, created_at INTEGER NOT NULL);
CREATE TABLE audit(id INTEGER PRIMARY KEY, run_id TEXT, operation TEXT NOT NULL, status TEXT NOT NULL, at INTEGER NOT NULL);
